create or replace function public.prevent_published_version_mutation() returns trigger language plpgsql as $$ begin if old.status = 'published' then raise exception 'Published architecture versions are immutable'; end if; return coalesce(new, old); end; $$;
create or replace function public.prevent_published_child_mutation() returns trigger language plpgsql as $$ begin if exists (select 1 from public.architecture_versions where id = old.architecture_version_id and status = 'published') then raise exception 'Published architecture versions are immutable'; end if; return coalesce(new, old); end; $$;

create table public.architecture_versions (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, version_number integer not null check (version_number > 0), name text not null, description text, status text not null default 'draft' check (status in ('draft', 'published', 'archived')), architecture_data jsonb not null default '{}'::jsonb, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(project_id, version_number));
create table public.architecture_nodes (id uuid primary key default gen_random_uuid(), architecture_version_id uuid not null references public.architecture_versions(id) on delete cascade, node_key text not null, name text not null, type text not null check (type in ('frontend', 'backend', 'service', 'database', 'cache', 'queue', 'storage', 'external_service', 'auth', 'worker', 'api', 'gateway', 'monitoring', 'infrastructure')), technology text, description text, metadata jsonb not null default '{}'::jsonb, position_x double precision not null default 0, position_y double precision not null default 0, created_at timestamptz not null default now(), unique(architecture_version_id, node_key));
create table public.architecture_edges (id uuid primary key default gen_random_uuid(), architecture_version_id uuid not null references public.architecture_versions(id) on delete cascade, source_node_id uuid not null references public.architecture_nodes(id) on delete cascade, target_node_id uuid not null references public.architecture_nodes(id) on delete cascade, relationship text not null check (relationship in ('calls', 'reads', 'writes', 'publishes', 'subscribes', 'authenticates', 'depends_on', 'connects_to')), protocol text, description text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), check (source_node_id <> target_node_id));
create table public.snapshots (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, architecture_version_id uuid not null references public.architecture_versions(id), name text not null, description text, type text not null check (type in ('milestone', 'sprint', 'beta', 'production', 'custom')), snapshot_data jsonb not null default '{}'::jsonb, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.timeline_events (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id), event_type text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

create index architecture_versions_project_idx on public.architecture_versions(project_id); create index architecture_nodes_version_idx on public.architecture_nodes(architecture_version_id); create index architecture_edges_version_idx on public.architecture_edges(architecture_version_id); create index snapshots_project_idx on public.snapshots(project_id); create index timeline_project_created_idx on public.timeline_events(project_id, created_at desc);
create trigger architecture_versions_immutable before update or delete on public.architecture_versions for each row execute function public.prevent_published_version_mutation();
create trigger architecture_nodes_version_immutable before update or delete on public.architecture_nodes for each row execute function public.prevent_published_child_mutation();
create trigger architecture_edges_version_immutable before update or delete on public.architecture_edges for each row execute function public.prevent_published_child_mutation();

alter table public.architecture_versions enable row level security; alter table public.architecture_nodes enable row level security; alter table public.architecture_edges enable row level security; alter table public.snapshots enable row level security; alter table public.timeline_events enable row level security;
create policy architecture_versions_access on public.architecture_versions for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy architecture_versions_insert on public.architecture_versions for insert with check (created_by = auth.uid() and public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy architecture_versions_update on public.architecture_versions for update using (public.is_workspace_admin((select workspace_id from public.projects where id = project_id)));
create policy architecture_nodes_access on public.architecture_nodes for select using (public.is_workspace_member((select p.workspace_id from public.projects p join public.architecture_versions v on v.project_id = p.id where v.id = architecture_version_id))); create policy architecture_nodes_manage on public.architecture_nodes for all using (public.is_workspace_admin((select p.workspace_id from public.projects p join public.architecture_versions v on v.project_id = p.id where v.id = architecture_version_id)));
create policy architecture_edges_access on public.architecture_edges for select using (public.is_workspace_member((select p.workspace_id from public.projects p join public.architecture_versions v on v.project_id = p.id where v.id = architecture_version_id))); create policy architecture_edges_manage on public.architecture_edges for all using (public.is_workspace_admin((select p.workspace_id from public.projects p join public.architecture_versions v on v.project_id = p.id where v.id = architecture_version_id)));
create policy snapshots_access on public.snapshots for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy snapshots_manage on public.snapshots for all using (public.is_workspace_member((select workspace_id from public.projects where id = project_id)));
create policy timeline_access on public.timeline_events for select using (public.is_workspace_member(workspace_id)); create policy timeline_insert on public.timeline_events for insert with check (user_id = auth.uid() and public.is_workspace_member(workspace_id));